changeSet.createProcedure:
CREATE FUNCTION public.guard_review_setup() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF ROW(NEW.id, NEW.workspace_id, NEW.item_kind, NEW.audience, NEW.created_at)
        IS DISTINCT FROM ROW(OLD.id, OLD.workspace_id, OLD.item_kind, OLD.audience, OLD.created_at)
        OR (OLD.removed_at IS NOT NULL AND NEW.removed_at IS DISTINCT FROM OLD.removed_at) THEN
        RAISE EXCEPTION 'a review setup keeps its kind and audience, and a removed one stays removed'
            USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END $$

CREATE FUNCTION public.admit_review_setup_team() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    PERFORM 1 FROM public.review_setup s
        WHERE s.id = NEW.setup_id AND s.workspace_id = NEW.workspace_id AND s.audience = 'TEAM';
    IF NOT FOUND THEN
        RAISE EXCEPTION 'only a team review setup names teams' USING ERRCODE = '23514';
    END IF;
    PERFORM 1 FROM public.project_team t
        WHERE t.id = NEW.team_id AND t.workspace_id = NEW.workspace_id AND t.removed_at IS NULL;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'a review setup names standing team projects of its workspace' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $$

changeSet.sql:
CREATE TRIGGER review_setup_guard AFTER UPDATE ON public.review_setup
    FOR EACH ROW EXECUTE FUNCTION public.guard_review_setup();
CREATE TRIGGER review_setup_team_admit BEFORE INSERT ON public.review_setup_team
    FOR EACH ROW EXECUTE FUNCTION public.admit_review_setup_team();
CREATE TRIGGER review_setup_team_still_admitted AFTER UPDATE ON public.review_setup_team
    FOR EACH ROW EXECUTE FUNCTION public.admit_review_setup_team();

changeSet.rollback:
DROP TRIGGER review_setup_team_still_admitted ON public.review_setup_team;
DROP TRIGGER review_setup_team_admit ON public.review_setup_team;
DROP TRIGGER review_setup_guard ON public.review_setup;
DROP FUNCTION public.admit_review_setup_team();
DROP FUNCTION public.guard_review_setup();

changeSet.createProcedure:
CREATE FUNCTION public.keep_project_team_workspace() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.id IS DISTINCT FROM OLD.id OR NEW.workspace_id IS DISTINCT FROM OLD.workspace_id THEN
        RAISE EXCEPTION 'a team project keeps its id and its workspace' USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END $$
